+    @Override
+    public OpenCLHATKernelBuilder hatTensorCreateOperation(OpHelper.Invoke invoke) {
+        List<Value> operands = invoke.op().operands();
+        if (operands.isEmpty()) {
+            return createTensor(invoke);
+        } else {
+            return createTensorAccumulator(invoke);
+        }
+    }
