+    private String generateVariableName(String prefix) {
+        String vocab = "abcdefghijklmnopqrstuvxyz";
+        Random r = new Random();
+        StringBuilder varA = new StringBuilder(prefix);
+        for (int i = 0; i < 3; i++) {
+            varA.append(vocab.charAt(r.nextInt(vocab.length())));
+        }
+        return varA.toString();
+    }
